/// Differential entry: runs the translation of `va`. True when `va` belongs to this module.
#[allow(unused_variables)]
pub fn run<M: GuestMemory, C: GuestCall>(
    va: u32,
    m: &mut M,
    guest: &mut C,
    regs: &mut ExtRegisters,
) -> bool {
    match va {
        0x3813da => sub_003813da(m, guest, regs),
        0x3ca970 => sub_003ca970(m, regs),
        0x3cce3d => sub_003cce3d(m, regs),
        0x3cf380 => sub_003cf380(m, regs),
        _ => return false,
    }
    true
}
